$p = "C:\Users\Administrator\.dsh\profiles\web\node_modules\@xbzbing\dsh-git-panel"
Write-Output "=== grep locale/de.json references in lib ==="
Get-ChildItem "$p\lib" -Recurse -File | ForEach-Object {
  $m = Select-String -Path $_.FullName -Pattern 'locale/(de|en|zh)\.json|locale/|\.json.?\)' -SimpleMatch -ErrorAction SilentlyContinue
  if($m){ "$($_.FullName): $($m.Count) hits" }
}
Write-Output "=== search for 'locale/' string across lib ==="
Get-ChildItem "$p\lib" -Recurse -File | Select-String -Pattern 'locale/' | Select-Object -First 30 | ForEach-Object { "$($_.Filename):$($_.LineNumber): $($_.Line.Trim())" }

$p = "C:\Users\Administrator\.dsh\profiles\web\node_modules\@xbzbing\dsh-git-panel"
Get-ChildItem "$p\lib" -Recurse -File -Filter *.js | ForEach-Object {
  $rel = $_.FullName.Substring($p.Length+1)
  $hits = Select-String -Path $_.FullName -Pattern 'locale\/(de|en|zh|ja|es|fr|ru|pt)\.json' -ErrorAction SilentlyContinue
  if($hits){ foreach($h in $hits){ "$rel : L$($h.LineNumber)" } }
}
Write-Output "=== structured locale loading code (short lines referencing 'locale' & readFile/import) ==="
Get-ChildItem "$p\lib" -Recurse -File -Filter *.js | ForEach-Object {
  $rel = $_.FullName.Substring($p.Length+1)
  $c = Get-Content $_.FullName
  for($i=0;$i -lt $c.Count;$i++){
    $line = $c[$i]
    if($line.Length -lt 300 -and $line -match 'locale' -and $line -match 'json|readFile|require|import'){ "$rel : $($i+1): $($line.Trim())" }
  }
} | Select-Object -First 40

$core = "D:\nvm\v22.23.2\node_modules\@deepseek-ai\dsh"
Write-Output "=== search core for the error template 'Plugin metadata for' ==="
Get-ChildItem $core -Recurse -File -Include *.js,*.mjs,*.cjs -ErrorAction SilentlyContinue | ForEach-Object {
  $h = Select-String -Path $_.FullName -Pattern 'Plugin metadata for' -ErrorAction SilentlyContinue
  if($h){ "$($_.FullName):$($h[0].LineNumber)" }
} | Select-Object -First 10
